import re, os, json, sys

root = '.'
reg_re = re.compile(r'\b((?:devm_)?request(?:_threaded)?_irq)\s*\(')
handler_re = re.compile(r'\b(\w+)\s*\(')

regs = []  # (file, line, api, handler)

for dirpath, dirnames, filenames in os.walk(root):
    for fn in filenames:
        if not fn.endswith(('.c', '.h')): continue
        p = os.path.join(dirpath, fn)
        try:
            with open(p, 'r', errors='ignore') as f:
                lines = f.readlines()
        except Exception:
            continue
        for i, ln in enumerate(lines):
            if not reg_re.search(ln): continue
            # gather wrapped lines until ');'
            chunk = ln
            j = i
            while not re.search(r'\)\s*;', chunk) and j < i + 6 and j + 1 < len(lines):
                j += 1
                chunk += lines[j]
            # find handler arg (non-threaded: 2nd arg; threaded: 2nd arg is primary, 3rd is thread)
            m_arg = re.search(r'\(\s*([^,]+?)\s*,\s*(\w+)\s*,', chunk)
            handlers = []
            mm = re.findall(r',\s*(\w+)\s*,', chunk)
            if 'threaded' in re.search(r'\b(\w+)\s*\(', chunk).group(1):
                # request_threaded_irq(irq, handler, thread_fn, ...)
                args = re.search(r'\(\s*([^,()]+),\s*([^,()]+),\s*([^,()]+),', chunk)
                if args:
                    for g in (2, 3):
                        v = args.group(g).strip()
                        if v and v not in ('NULL', '0'):
                            handlers.append((v, 'primary' if g == 2 else 'thread'))
            else:
                args = re.search(r'\(\s*([^,()]+),\s*([^,()]+),', chunk)
                if args:
                    v = args.group(2).strip()
                    if v and v not in ('NULL', '0'):
                        handlers.append((v, 'hardirq'))
            for h, role in handlers:
                regs.append((p, i + 1, 'handler', h, role))

print(len(regs))
import collections
print(collections.Counter(r[3] for r in regs).most_common(5))
with open(os.environ.get('TMPDIR', '/tmp') + '/i047/regs.txt', 'w') as f:
    for r in regs:
        f.write('\t'.join(map(str, r)) + '\n')
